      {
        "type": "heading",
        "text": "Solution"
      },
      {
        "type": "code",
        "language": "javascript",
        "text": "class Solution {\n    public void mergeArrays(int a[], int b[]) {\n        // code here\n        // better approach without using extra space  \n        int m=a.length;\n        int n=b.length;\n        for(int i=0;i<Math.min(m,n);i++){\n            if(a[m-1-i]>b[i]){\n                int temp=a[m-1-i];\n                a[m-1-i]=b[i];\n                b[i]=temp;\n            }\n        }\n        Arrays.sort(a);\n        Arrays.sort(b);\n    }\n}"
      }
